-- Connector sync receipts (step 6): one CONNECTOR_*_RECEIVED event plus a
-- foundation delivery per successful connector sync. Extends the events
-- type check only; no new tables (emission reuses events/event_deliveries).
ALTER TABLE events DROP CONSTRAINT IF EXISTS events_event_type_check;
ALTER TABLE events ADD CHECK(event_type IN ('EMAIL_RECEIVED','EMAIL_REPLIED','CALENDAR_CHANGED','FILE_CREATED','FILE_MODIFIED','FILE_DELETED','FILE_SHARED','COMPUTER_CONNECTED','COMPUTER_DISCONNECTED','DEVICE_EVENT','SCHEDULE_TRIGGER','TIMER_TRIGGER','WEBHOOK_RECEIVED','GITHUB_EVENT','HOME_EVENT','TASK_COMPLETED','TASK_FAILED','USER_MESSAGE','AGENT_MESSAGE','APPROVAL_ACCEPTED','APPROVAL_DENIED','CONNECTOR_CALENDAR_RECEIVED','CONNECTOR_HA_RECEIVED','CONNECTOR_GITHUB_RECEIVED','CONNECTOR_INBOX_RECEIVED'));
